//! Test-only TLS helpers — self-signed certs via `rcgen`.
//!
//! `rcgen` is a `dev-dependencies` entry so it never ships in
//! production builds. This module is `#[cfg(test)]`-gated to make
//! the same compile-time guarantee on the dist crate side.

#![cfg(test)]
#![allow(dead_code)] // helpers are consumed across sub-phases (3-node ring lands at M14.5)

use rustls::pki_types::{CertificateDer, PrivateKeyDer, PrivatePkcs8KeyDer};

use crate::tls_config::TlsConfig;
use crate::DistError;

/// One node's identity material — generated by [`pair`] / [`triple`].
pub struct DevIdentity {
    pub name: String,
    pub config: TlsConfig,
}

/// Bundled CA material — caller can use the held cert + keypair to
/// sign multiple leaf certs against one CA, or pass a different CA
/// to alternate clusters in cert-mismatch tests.
pub struct DevCa {
    pub cert: rcgen::Certificate,
    pub keypair: rcgen::KeyPair,
    pub cert_der: CertificateDer<'static>,
}

/// Issue two `TlsConfig`s sharing a single test CA. Each side trusts
/// the CA, so a TLS handshake between them succeeds. Each leaf cert
/// has SAN = node name so client-side `ServerName` verification
/// picks up the right identity.
pub fn pair(name_a: &str, name_b: &str) -> Result<(DevIdentity, DevIdentity), DistError> {
    let ca = make_ca()?;
    let a = issue(&ca, name_a, true)?;
    let b = issue(&ca, name_b, true)?;
    Ok((a, b))
}

/// Issue N `TlsConfig`s sharing a single test CA. Order matches the
/// input slice. Useful for three-node ring tests.
pub fn triple(names: &[&str]) -> Result<Vec<DevIdentity>, DistError> {
    let ca = make_ca()?;
    names.iter().map(|n| issue(&ca, n, true)).collect()
}

/// Issue a `TlsConfig` against an already-built CA. Lets tests
/// generate two CAs and chain certs to each separately for
/// cert-mismatch coverage.
pub fn issue(ca: &DevCa, name: &str, require_mtls: bool) -> Result<DevIdentity, DistError> {
    let mut leaf_params = rcgen::CertificateParams::new(vec![name.to_string()])
        .map_err(|e| DistError::Tls(format!("leaf params: {e}")))?;
    leaf_params.subject_alt_names.push(rcgen::SanType::DnsName(
        name.to_string()
            .try_into()
            .map_err(|e: rcgen::Error| DistError::Tls(format!("san dns name: {e}")))?,
    ));
    let leaf_key = rcgen::KeyPair::generate()
        .map_err(|e| DistError::Tls(format!("leaf keygen: {e}")))?;
    let leaf_cert = leaf_params
        .signed_by(&leaf_key, &ca.cert, &ca.keypair)
        .map_err(|e| DistError::Tls(format!("leaf sign: {e}")))?;
    let cert_der: CertificateDer<'static> = leaf_cert.der().clone();
    let key_der: PrivateKeyDer<'static> =
        PrivatePkcs8KeyDer::from(leaf_key.serialize_der()).into();

    let cfg = TlsConfig::from_pem_bytes(
        vec![cert_der],
        key_der,
        vec![ca.cert_der.clone()],
        require_mtls,
    )?;
    Ok(DevIdentity {
        name: name.to_string(),
        config: cfg,
    })
}

/// Build a fresh test CA. Each call gets a brand-new keypair, so
/// two CAs from two `make_ca()` calls won't trust each other (used
/// for cert-mismatch rejection coverage).
pub fn make_ca() -> Result<DevCa, DistError> {
    let mut params = rcgen::CertificateParams::new(vec!["graphreact-dist test CA".into()])
        .map_err(|e| DistError::Tls(format!("ca params: {e}")))?;
    params.is_ca = rcgen::IsCa::Ca(rcgen::BasicConstraints::Unconstrained);
    let keypair =
        rcgen::KeyPair::generate().map_err(|e| DistError::Tls(format!("ca keygen: {e}")))?;
    let cert = params
        .self_signed(&keypair)
        .map_err(|e| DistError::Tls(format!("ca self-sign: {e}")))?;
    let cert_der: CertificateDer<'static> = cert.der().clone();
    Ok(DevCa {
        cert,
        keypair,
        cert_der,
    })
}
